window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[25]={"id":"025","numero":25,"titre":"Grossesse extra-utérine","objectifs":[{"id":"25-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la Grossesse Extra-utérine (GEU)","contenu":"<p><span class=\"kw-def\">Grossesse extra-utérine (GEU)</span> = <strong>nidation de l’œuf en dehors de la cavité utérine</strong>, aussi appelée <span class=\"kw-def\">grossesse ectopique</span>. La nidation s’effectue de façon ectopique lorsque la <strong>motilité tubaire est altérée</strong> (altération/destruction des cils vibratiles tubaires, ou reflux tubaire).</p>\n\n      <h4>Rappel — Situation physiologique</h4>\n\n      <ul>\n        <li>Fécondation dans le <span class=\"kw-chiffre\">1/3 distal de la trompe</span> (au niveau de l’ampoule)</li>\n        <li>L’œuf migre dans la cavité utérine <em>via la motilité tubaire</em></li>\n        <li>L’œuf entame sa <strong>nidation <span class=\"kw-chiffre\">7 jours</span> après</strong> (quel que soit l’endroit où il se trouve)</li>\n      </ul>\n\n      <h4>Localisations possibles de GEU</h4>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/25/localisations-geu-distribution.png\" alt=\"Schéma anatomique de la distribution des localisations possibles de GEU : tubaire 95%, ovarienne 3%, abdominale 0.9-1.4%, interstitielle 2-4%, cervicale, cicatrice de césarienne, hétérotopique, intramurale\" loading=\"lazy\">\n        <figcaption>Distribution anatomique des localisations possibles de GEU. La grande majorité (≈<span class=\"kw-chiffre\">95%</span>) sont <span class=\"kw-clinique\">tubaires</span> (ampullaires <span class=\"kw-chiffre\">70%</span>, isthmiques <span class=\"kw-chiffre\">20%</span>, pavillonnaires <span class=\"kw-chiffre\">5%</span>). Source : radiopaedia.org/cases/ectopic-pregnancy-distribution-diagram.</figcaption>\n      </figure>\n\n      <table >\n        <thead>\n          <tr><th>Localisation</th><th>Fréquence</th><th>Particularités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ci\">Grossesse</span> tubaire</strong></td>\n            <td><span class=\"kw-chiffre\">≈ 95 %</span></td>\n            <td>\n              <strong>Ampullaire :</strong> <span class=\"kw-chiffre\">70 %</span> (localisation la plus fréquente)<br>\n              <strong>Isthmique :</strong> <span class=\"kw-chiffre\">20 %</span><br>\n              <strong>Pavillonnaire :</strong> <span class=\"kw-chiffre\">5 %</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Localisations plus rares</strong></td>\n            <td><span class=\"kw-chiffre\">&lt; 5 %</span></td>\n            <td><span class=\"kw-clinique\">Interstitielle</span> (partie utérine de la trompe), <span class=\"kw-clinique\">ovarienne</span>, <span class=\"kw-clinique\">abdominale</span></td>\n          </tr>\n          <tr>\n            <td><strong>Localisations exceptionnelles</strong></td>\n            <td><span class=\"kw-chiffre\">&lt; 1 %</span></td>\n            <td><span class=\"kw-clinique\">Cervicale</span> (col de l’utérus), <span class=\"kw-clinique\">isthmique sur cicatrice de césarienne</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Cas particulier — <span class=\"kw-ci\">Grossesse</span> hétérotopique</h4>\n\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-ci\">Grossesse</span> hétérotopique.</strong> Coexistence de <strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> g</span>rossesses simultanées</strong> : <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> g</span>rossesse intra-utérine (GIU) + 1 GEU. Fréquence spontanée : <span class=\"kw-chiffre\">1 / 10 000 à 30 000</span> grossesses. <strong>Principal FR :</strong> <span class=\"kw-clinique\">procréation médicalement assistée</span> (FIV ++). À évoquer systématiquement chez une femme enceinte sous PMA présentant des douleurs pelviennes, même si une GIU est confirmée.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 40 — Algies pelviennes · 43 — Hémorragie génitale chez la femme</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/cases/ectopic-pregnancy-distribution-diagram","label":"Radiopaedia : Ectopic pregnancy — distribution diagram"}]},{"id":"25-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître l’évolution naturelle de la GEU","contenu":"<p>L’<span class=\"kw-clinique\">évolution</span> naturelle de la GEU non traitée suit une <strong>séquence physiopathologique progressive</strong> qui peut conduire à un <span class=\"kw-alerte\">choc</span> <span class=\"kw-etio\">hémorragique</span> et au décès. À ce titre, la GEU constitue une <span class=\"kw-alerte\">urgence thérapeutique</span>.</p>\n\n      <h4>Cascade évolutive</h4>\n\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Mécanisme</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. <span class=\"kw-clinique\">Distension tubaire</span></strong></td>\n            <td>Croissance du trophoblaste dans une trompe inextensible → <span class=\"kw-clinique\">distension excessive</span>, accompagnée d’un <span class=\"kw-clinique\">hématosalpynx</span> (collection sanguine intratubaire) éventuel.</td>\n          </tr>\n          <tr>\n            <td><strong>2. <span class=\"kw-alerte\">Rupture</span> tubaire</strong></td>\n            <td><span class=\"kw-alerte\">Rupture mécanique</span> de la trompe sous l’effet de la distension.</td>\n          </tr>\n          <tr>\n            <td><strong>3. Hémopéritoine</strong></td>\n            <td>Issue brutale de sang dans la cavité péritonéale.</td>\n          </tr>\n          <tr>\n            <td><strong>4. <span class=\"kw-alerte\">Choc</span> <span class=\"kw-etio\">hémorragique</span></strong></td>\n            <td><span class=\"kw-alerte\">Hypovolémie aiguë</span> par déperdition sanguine massive → instabilité hémodynamique.</td>\n          </tr>\n          <tr>\n            <td><strong>5. Décès</strong></td>\n            <td><span class=\"kw-alerte\">Issue exceptionnelle</span> avec la prise en charge moderne, mais possible.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 124\" role=\"img\" aria-label=\"Frise de l'évolution naturelle de la grossesse extra-utérine non traitée : distension tubaire avec hématosalpynx éventuel, puis rupture tubaire mécanique, puis hémopéritoine par issue de sang dans le péritoine, puis choc hémorragique par hypovolémie aiguë, et enfin décès, issue exceptionnelle mais possible.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"20\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\"><span class=\"kw-clinique\">Évolution</span> naturelle de la GEU non traitée</text>\n          <rect class=\"fb-amber\" x=\"8\" y=\"44\" width=\"96\" height=\"68\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"56\" y=\"70\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"600\">Distension</text>\n          <text class=\"tx-amber\" x=\"56\" y=\"84\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"600\">tubaire</text>\n          <text class=\"tx-amber\" x=\"56\" y=\"100\" text-anchor=\"middle\" font-size=\"8\">± hématosalpynx</text>\n          <rect class=\"fb-amber\" x=\"120\" y=\"44\" width=\"96\" height=\"68\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"168\" y=\"70\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"600\"><span class=\"kw-alerte\">Rupture</span></text>\n          <text class=\"tx-amber\" x=\"168\" y=\"84\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"600\">tubaire</text>\n          <text class=\"tx-amber\" x=\"168\" y=\"100\" text-anchor=\"middle\" font-size=\"8\">(mécanique)</text>\n          <rect class=\"fb-red\" x=\"232\" y=\"44\" width=\"96\" height=\"68\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"280\" y=\"77\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"600\">Hémopéritoine</text>\n          <text class=\"tx-red\" x=\"280\" y=\"93\" text-anchor=\"middle\" font-size=\"8\">sang intra-périt.</text>\n          <rect class=\"fb-red\" x=\"344\" y=\"44\" width=\"96\" height=\"68\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"392\" y=\"70\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"600\"><span class=\"kw-alerte\">Choc</span></text>\n          <text class=\"tx-red\" x=\"392\" y=\"84\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"600\"><span class=\"kw-etio\">hémorragique</span></text>\n          <text class=\"tx-red\" x=\"392\" y=\"100\" text-anchor=\"middle\" font-size=\"8\">hypovolémie aiguë</text>\n          <rect class=\"fb-red\" x=\"456\" y=\"44\" width=\"96\" height=\"68\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"504\" y=\"77\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"600\">Décès</text>\n          <text class=\"tx-red\" x=\"504\" y=\"93\" text-anchor=\"middle\" font-size=\"8\">(exceptionnel)</text>\n          <line class=\"ln\" x1=\"105\" y1=\"78\" x2=\"116\" y2=\"78\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"120,78 114,74 114,82\"/>\n          <line class=\"ln\" x1=\"217\" y1=\"78\" x2=\"228\" y2=\"78\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"232,78 226,74 226,82\"/>\n          <line class=\"ln\" x1=\"329\" y1=\"78\" x2=\"340\" y2=\"78\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"344,78 338,74 338,82\"/>\n          <line class=\"ln\" x1=\"441\" y1=\"78\" x2=\"452\" y2=\"78\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"456,78 450,74 450,82\"/>\n        </svg>\n        <figcaption>Séquence physiopathologique progressive : toute GEU non traitée est une <span class=\"kw-alerte\">urgence</span> thérapeutique (jusqu’au choc hémorragique et au décès).</figcaption>\n      </figure>\n\n      <div class=\"callout callout-warn\">\n        <strong>Issue alternative rare.</strong> Selon le KB, l’<span class=\"kw-def\">avortement tubo-abdominal</span> peut <em>exceptionnellement</em> aboutir à la guérison spontanée de la patiente (expulsion de l’œuf dans la cavité péritonéale avec résorption progressive). Cas anecdotique non pris en compte dans la stratégie de prise en charge — toute GEU diagnostiquée doit être traitée.\n      </div>\n\n      <h4>Localisations historiques (à connaître)</h4>\n\n      <p><em>Ancien référentiel</em> : <span class=\"kw-clinique\">grossesses cervicales</span>, <span class=\"kw-clinique\">grossesses diverticulaires</span> (endométriose), <span class=\"kw-clinique\">grossesses angulaires</span>, <span class=\"kw-clinique\">grossesses dans les utérus malformés</span> (ex : corne utérine rudimentaire) — rares, mais avec un <span class=\"kw-alerte\">pronostic vital</span> souvent plus sombre du fait de la richesse vasculaire (<span class=\"kw-alerte\">rupture</span> <span class=\"kw-etio\">hémorragique</span> plus précoce et plus massive).</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — État de <span class=\"kw-alerte\">choc</span> · 24 — Complications de la <span class=\"kw-ci\">grossesse</span> · 43 — Hémorragie génitale chez la femme</em></p>","frequence":0},{"id":"25-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’incidence de la GEU et les facteurs de risque","contenu":"<p>La GEU est une pathologie <strong>fréquente</strong> dont l’<span class=\"kw-def\">incidence</span> a <span class=\"kw-alerte\">doublé en 15 ans</span> dans les pays développés. Les FR de GEU sont <strong>tous les facteurs altérant la motilité tubaire</strong>.</p>\n\n      <h4><span class=\"kw-def\">Épidémiologie</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Paramètre</th><th>Valeur</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Incidence</span> en France</strong></td>\n            <td><span class=\"kw-chiffre\">≈ 14 000 / an</span> — <span class=\"kw-def\">incidence</span> doublée en <span class=\"kw-chiffre\">15 ans</span>, en lien avec la recrudescence de certains FR (infections génitales hautes, <span class=\"kw-ttt\">chirurgie</span> tubaire, <span class=\"kw-etio\">tabac</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Fréquence</strong></td>\n            <td><span class=\"kw-chiffre\">2 %</span> des grossesses en France</td>\n          </tr>\n          <tr>\n            <td><strong>Morbi-<span class=\"kw-def\">mortalité</span></strong></td>\n            <td>\n              Reste non négligeable mais a très sensiblement diminué grâce à :<br>\n              <strong><span class=\"kw-def\">Diagnostic précoce</span></strong> (β-hCG + <span class=\"kw-imagerie\">échographie</span> endovaginale précoce)<br>\n              <strong>Traitements moins invasifs</strong> (<span class=\"kw-ttt\">méthotrexate</span>, cœlioscopie)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Facteurs de risque</span> — <span class=\"kw-def\">Classification</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Facteurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>\n              <span class=\"kw-clinique\">Âge maternel élevé (&gt; 35 ans)</span><br>\n              <span class=\"kw-clinique\">Tabagisme</span> avec relation dose-effet<br>\n              <span class=\"kw-clinique\">ATCD de GEU</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>ATCD <span class=\"kw-etio\">infectieux</span></strong> ⭐</td>\n            <td>\n              <span class=\"kw-clinique\">Infection génitale haute (IGH ++)</span> — <span class=\"kw-etio\">salpingites</span>, <span class=\"kw-etio\">endométrites</span>, <span class=\"kw-chiffre\">RR × 6</span> ; <span class=\"kw-etio\">Chlamydia trachomatis</span> est le germe le plus fréquemment en cause<br>\n              <span class=\"kw-clinique\">Chirurgie tubaire</span> ou <span class=\"kw-clinique\">chirurgie abdominopelvienne à risque d’adhérences</span> (pelvipéritonite, myomectomie...)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Altération de la paroi tubaire</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Endométriose tubaire</span><br>\n              <span class=\"kw-etio\">Tuberculose</span>, <span class=\"kw-clinique\">bilharziose</span><br>\n              <span class=\"kw-clinique\">Malformation utérine ou tubaire</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fécondation</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Fécondation in vitro (FIV)</span> : GEU surviennent dans <span class=\"kw-chiffre\">4,5 %</span> des FIV → penser systématiquement aux <strong>grossesses hétérotopiques</strong>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Contraception</strong> <em>(controversé)</em></td>\n            <td>\n              <strong>Réf gynéco :</strong> <span class=\"kw-ttt\">microprogestatif</span>, <span class=\"kw-ttt\">DIU</span> (RR = 3) sont des FR.<br>\n              <strong>HAS :</strong> DIU n’est <span class=\"kw-alerte\">pas</span> un FR de GEU.<br>\n              <strong>KB (synthèse) :</strong> DIU au cuivre n’est pas un FR de GEU au sens strict, mais prévient moins bien la GEU que la GIU (empêche la nidation mais pas totalement la fécondation) → si <span class=\"kw-ci\">grossesse</span> sous DIU, <strong>forte probabilité de GEU</strong>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège QCM classique.</strong> La <span class=\"kw-etio\">Chlamydia trachomatis</span> est le germe le plus fréquemment en cause dans les <span class=\"kw-clinique\">IGH</span> à l’origine d’une GEU. À retenir comme paire dans les QCM : « GEU + ATCD d’IST → penser <span class=\"kw-etio\">Chlamydia</span> + <span class=\"kw-def\">dépistage</span> IST chez patiente et partenaire ».\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — IST · 36 — Contraception · 75 — Addiction <span class=\"kw-etio\">tabac</span> · 42 — Aménorrhée</em></p>","frequence":3},{"id":"25-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le diagnostic clinique de la GEU et le diagnostic différentiel en cas de douleurs pelviennes et/ou de métrorragies","contenu":"<div class=\"callout callout-danger\">\n        <strong>Dogme fondamental.</strong> Toute <span class=\"kw-alerte\">femme en âge de procréer</span> présentant des <span class=\"kw-clinique\">douleurs pelviennes</span> et/ou des <span class=\"kw-clinique\">métrorragies</span> = <strong>GEU jusqu’à preuve du contraire</strong>. Triade diagnostique systématique : <strong>examen clinique + <span class=\"kw-imagerie\">échographie</span> pelvienne (endovaginale + abdominale) + dosage des β-hCG</strong>.\n      </div>\n\n      <h4>Interrogatoire</h4>\n\n      <ul>\n        <li>Préciser la <strong>date des dernières règles</strong> (DDR) — pour le calcul de l’âge gestationnel</li>\n        <li>Rechercher les <strong>FR de GEU</strong> (cf. obj-2)</li>\n      </ul>\n\n      <h4>Symptômes cliniques</h4>\n\n      <table >\n        <thead>\n          <tr><th>Symptôme</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>GEU asymptomatique</strong></td>\n            <td>Possible — la GEU peut être <span class=\"kw-alerte\">totalement asymptomatique</span> au <span class=\"kw-def\">stade</span> précoce.</td>\n          </tr>\n          <tr>\n            <td><strong>Métrorragies</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Peu abondantes</span><br>\n              <span class=\"kw-clinique\">Foncées / noirâtres</span>, classiquement « <strong>sépia</strong> »<br>\n              <em>À distinguer</em> des métrorragies <strong>rouges et abondantes</strong> de la fausse couche spontanée\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Douleurs pelviennes</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Latéralisées</span> (du côté de la GEU ou non)<br>\n              <span class=\"kw-clinique\">Sourdes</span>, avec des <span class=\"kw-clinique\">accès plus intenses</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Signes sympathiques de <span class=\"kw-ci\">grossesse</span></strong></td>\n            <td><span class=\"kw-clinique\">Nausées</span>, <span class=\"kw-clinique\">vomissements</span>, tension mammaire, somnolence, <span class=\"kw-clinique\">pollakiurie</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Signes dans les formes évoluées</strong> (hémopéritoine)</td>\n            <td>\n              <span class=\"kw-alerte\">Scapulalgies</span> (irritation diaphragmatique)<br>\n              <span class=\"kw-alerte\">Malaise, agitation, angoisse</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Examen clinique</h4>\n\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Signes recherchés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Examen général</strong></td>\n            <td>\n              Abdomen douloureux de façon <strong>latéralisée</strong>, avec ou sans défense, voire contracture généralisée.<br>\n              <span class=\"kw-alerte\">Signes de mauvaise tolérance hémodynamique</span> évoquant une GEU rompue : <span class=\"kw-clinique\">hypotension</span>, <span class=\"kw-clinique\">tachycardie</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Spéculum</strong></td>\n            <td>Précise l’<strong>origine endo-utérine</strong> des saignements (élimine une <span class=\"kw-clinique\">lésion</span> cervicale ou vaginale).</td>\n          </tr>\n          <tr>\n            <td><strong>Toucher vaginal (<span class=\"kw-alerte\">TV</span>)</strong></td>\n            <td>\n              <strong>Col</strong> tonique et fermé<br>\n              <strong>Utérus</strong> moins gros qu’attendu (par rapport à l’âge gestationnel)<br>\n              <strong><span class=\"kw-clinique\">Masse</span> latéro-utérine douloureuse</strong> : parfois palpée<br>\n              <strong>Douleurs provoquées</strong> : dans un cul-de-sac latéral, dans le <span class=\"kw-clinique\">cul-de-sac recto-utérin (Douglas)</span> ou à la <span class=\"kw-clinique\">mobilisation utérine</span><br>\n              <em>Empâtement du cul-de-sac de Douglas</em> dans les formes avec hémopéritoine\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Diagnostics différentiels</h4>\n\n      <table >\n        <thead>\n          <tr><th>Contexte</th><th>Diagnostics à évoquer</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Avec β-hCG positifs</strong></td>\n            <td>\n              <span class=\"kw-etio\">Grossesse intra-utérine (GIU)</span><br>\n              <span class=\"kw-etio\">Fausse couche spontanée (FCS)</span><br>\n              <span class=\"kw-etio\">Môle hydatiforme</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Avec β-hCG négatifs</strong></td>\n            <td>\n              <span class=\"kw-etio\">Kyste hémorragique du corps jaune</span><br>\n              <strong>Autres causes de saignements</strong> (spéculum ++) : <span class=\"kw-etio\">tumeur du col utérin</span>, <span class=\"kw-etio\">lésion traumatique cervicovaginale</span>, <span class=\"kw-etio\">fibrome</span><br>\n              <strong>Autres causes de douleurs :</strong> <span class=\"kw-etio\">salpingite aiguë</span>, <span class=\"kw-etio\">torsion d’annexe</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 40 — Algies pelviennes · 43 — Hémorragie génitale chez la femme · 162 — IST · 50 — Pathologie génito-scrotale</em></p>","frequence":4},{"id":"25-5","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes cliniques nécessitant une prise en charge en urgence","contenu":"<p>L’identification d’une <span class=\"kw-alerte\">GEU rompue</span> ou d’une <span class=\"kw-alerte\">menace de rupture imminente</span> impose une <strong>cœlioscopie en <span class=\"kw-alerte\">urgence</span></strong> à visée diagnostique <em>et</em> thérapeutique. Tout retard expose à un <span class=\"kw-alerte\">choc hémorragique</span>.</p>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Signes de gravité</span> = <span class=\"kw-alerte\">URGENCE</span> CHIRURGICALE.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Hypotension artérielle</span> (PAS &lt;<span class=\"kw-chiffre\"> 90 mmHg</span>)</li>\n          <li><span class=\"kw-alerte\">Tachycardie</span> (signe précoce de spoliation sanguine)</li>\n          <li><span class=\"kw-alerte\">Malaise</span>, <span class=\"kw-clinique\">lipothymie</span>, perte de connaissance</li>\n          <li><span class=\"kw-alerte\">Douleurs abdomino-pelviennes intenses</span></li>\n          <li><span class=\"kw-alerte\">Défense ou contracture abdominale</span> (péritonite <span class=\"kw-etio\">hémorragique</span>)</li>\n          <li><span class=\"kw-alerte\">Scapulalgies</span> (irritation diaphragmatique par hémopéritoine)</li>\n          <li><span class=\"kw-alerte\">Hémopéritoine</span> à l’<span class=\"kw-imagerie\">échographie</span> (épanchement dans le cul-de-sac de Douglas et/ou espace de Morisson)</li>\n        </ul>\n      </div>\n\n      <h4>Conduite à tenir devant ces signes</h4>\n\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Action</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Conditionnement</strong></td>\n            <td>\n              <strong>Expansion volémique</strong> (cristalloïdes)<br>\n              <strong>2 VVP de bon calibre</strong><br>\n              <strong><span class=\"kw-def\">Bilan préopératoire</span></strong> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">TP</span>/<span class=\"kw-bio\">TCA</span>, groupe-rhésus, RAI)<br>\n              <span class=\"kw-bio\">HemoCue®</span> (mesure rapide de l’<span class=\"kw-bio\">hémoglobine</span>)<br>\n              <strong>Appel du médecin anesthésiste</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2. Cœlioscopie en <span class=\"kw-alerte\">urgence</span></strong></td>\n            <td>Geste diagnostique <em>et</em> thérapeutique. <strong>Laparotomie</strong> si hémopéritoine massif et état de <span class=\"kw-def\">choc hypovolémique</span> (seule indication actuelle de la laparotomie : CI générales et locales à la cœlioscopie).</td>\n          </tr>\n          <tr>\n            <td><strong>3. <span class=\"kw-def\">Prévention secondaire</span></strong></td>\n            <td>Si <strong>Rh-</strong> : <span class=\"kw-ttt\">Ig anti-D</span> en post-opératoire (prévention de l’allo-immunisation anti-D).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — État de <span class=\"kw-alerte\">choc</span> · 338 — <span class=\"kw-clinique\">Œdème</span> de Quincke - <span class=\"kw-alerte\">anaphylaxie</span> · 162 — IST · 43 — Hémorragie génitale chez la femme</em></p>","frequence":0},{"id":"25-6","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à demander devant une suspicion de GEU","contenu":"<p>Le <span class=\"kw-def\">diagnostic positif</span> de GEU repose sur le <strong>couplage indissociable</strong> : <span class=\"kw-bio\">β-hCG plasmatique</span> + <span class=\"kw-imagerie\">échographie pelvienne</span> (<strong>endovaginale + abdominale</strong>), à réaliser <span class=\"kw-alerte\">systématiquement et sans délai</span>.</p>\n\n      <h4>1. Dosage des β-hCG plasmatiques</h4>\n\n      <p>Le dosage des β-hCG est le <strong>seul examen qui permet d’éliminer le diagnostic de <span class=\"kw-ci\">grossesse</span></strong> (et donc de GEU) s’il est négatif. <em>Les seuils détaillés et la cinétique sont traités dans l’obj-6.</em></p>\n\n      <h4>2. <span class=\"kw-imagerie\">Échographie</span> pelvienne — Voies systématiques</h4>\n\n      <table >\n        <thead>\n          <tr><th>Voie</th><th>Indication</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span> endovaginale</strong></td>\n            <td>Voie de référence — meilleure résolution sur l’utérus et les annexes. <strong>Systématique et sans délai</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie abdominale</span></strong></td>\n            <td><strong>Complète</strong> l’endovaginale — recherche d’<span class=\"kw-alerte\">hémopéritoine</span> (Douglas, gouttières pariétocoliques, espace de Morisson).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Signes échographiques</h4>\n\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Signes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Signes indirects</strong></td>\n            <td>\n              <span class=\"kw-radio\">Vacuité utérine</span> + <span class=\"kw-imagerie\">endomètre épais, gravide</span> + <span class=\"kw-bio\">[β-hCG &gt; 1000-1500 UI/L]</span> ou <strong>âge gestationnel &gt; 5,5 SA</strong><br>\n              <span class=\"kw-alerte\">Attention au pseudo-sac</span> ⚠️ : image lacunaire <strong>hypoéchogène</strong>, <strong>centrée dans la cavité</strong>, <strong>sans couronne trophoblastique</strong> (souvent un caillot de sang en voie d’expulsion)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Signes directs</strong></td>\n            <td>\n              <span class=\"kw-radio\">Image annexielle ou masse latéro-utérine</span> (située du côté du <strong>corps jaune dans <span class=\"kw-chiffre\">90 %</span></strong> des cas) pouvant correspondre à :<br>\n              <strong><span class=\"kw-radio\">Hématosalpynx</span></strong> : <span class=\"kw-radio\">masse latéro-utérine hétérogène</span><br>\n              <strong><span class=\"kw-radio\">Sac gestationnel extra-utérin</span></strong> : <span class=\"kw-imagerie\">image en cocarde (1-2 cm)</span> avec une <strong>couronne échogène</strong> (trophoblaste) et un <strong>centre clair</strong> ; <em>exceptionnellement, activité cardiaque embryonnaire visible</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span> normale ?</strong></td>\n            <td>\n              Dans <span class=\"kw-chiffre\">15 à 20 %</span> des GEU, <strong>aucun signe échographique n’est visible</strong> au premier examen.<br>\n              → Si absence de <span class=\"kw-alerte\">signes de gravité</span> : <strong>répéter l’examen à<span class=\"kw-chiffre\"> 48h</span></strong> en y associant une cinétique des β-hCG.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-alerte\">Signes de gravité</span> échographiques</h4>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/25/espace-morisson-hemoperitoine.png\" alt=\"Schéma anatomique de l'espace de Morisson, espace inter-hépato-rénal, où s'accumule le sang en cas d'hémopéritoine massif chez une patiente en décubitus dorsal\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Espace de Morisson</span> (espace inter-hépato-rénal) — région la plus déclive de la cavité péritonéale en décubitus dorsal. La présence de sang dans cet espace signe un <span class=\"kw-alerte\">hémopéritoine important</span> → nécessite une prise en charge chirurgicale 🔥 en extrême <span class=\"kw-alerte\">urgence</span>. Source : fiche source EDN item 25.</figcaption>\n      </figure>\n\n      <ol>\n        <li><strong>Rechercher un <span class=\"kw-radio\">épanchement dans le cul-de-sac recto-utérin (Douglas)</span></strong> — témoigne de la souffrance tubaire</li>\n        <li>Si présent, <strong>quantifier</strong> et compléter par une <strong><span class=\"kw-imagerie\">échographie abdominale</span></strong></li>\n        <li><strong>Présence de sang dans l’espace de Morisson</strong> (espace inter-hépato-rénal) = signe d’un <span class=\"kw-alerte\">hémopéritoine important</span> → <strong>prise en charge chirurgicale en extrême <span class=\"kw-alerte\">urgence</span></strong></li>\n      </ol>\n\n      <h4>Cœlioscopie diagnostique</h4>\n\n      <div class=\"callout callout-danger\">\n        <strong>Indication cœlioscopie en <span class=\"kw-alerte\">urgence</span>.</strong> Patiente présentant des <span class=\"kw-alerte\">signes de gravité</span> (<span class=\"kw-clinique\">hypotension</span>, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-alerte\">malaise</span>, douleurs intenses, défense, contracture) <strong>ou</strong> doute diagnostique chez une patiente <em>symptomatique (douleurs)</em>. La cœlioscopie confirme le diagnostic <em>et</em> permet le traitement dans le même temps opératoire.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 43 — Hémorragie génitale chez la femme · 332 — État de <span class=\"kw-alerte\">choc</span> · 50 — Pathologie génito-scrotale</em></p>","frequence":4,"liens":[{"href":"https://radiopaedia.org/articles/ectopic-pregnancy","label":"Radiopaedia : Ectopic pregnancy"}]},{"id":"25-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’évolution du dosage sanguin de Beta HCG et le diagnostic de GEU","contenu":"<p>Le dosage des <span class=\"kw-bio\">β-hCG plasmatiques</span> et leur <strong>cinétique</strong> sont au cœur du diagnostic de GEU. C’est le <strong>seul examen qui permet d’éliminer le diagnostic de <span class=\"kw-ci\">grossesse</span></strong> s’il est négatif.</p>\n\n      <h4>Seuils diagnostiques — Premier dosage</h4>\n\n      <table >\n        <thead>\n          <tr><th>Seuil β-hCG</th><th>Interprétation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>β-hCG <span class=\"kw-chiffre\">&gt; 1 500 UI/L</span></strong><br>(ou hCG <span class=\"kw-chiffre\">&gt; 3 510 UI/L</span>)</td>\n            <td>\n              <span class=\"kw-alerte\">GEU très probable</span> si <strong>vacuité utérine</strong> à l’<span class=\"kw-imagerie\">échographie</span> endovaginale.<br>\n              <em>À ce seuil, une GIU évolutive devrait être visible à l’écho endovaginale.</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>β-hCG <span class=\"kw-chiffre\">&lt; 1 500 UI/L</span></strong></td>\n            <td>\n              En l’absence de <span class=\"kw-alerte\">signes de gravité</span>, <strong>répéter le dosage à<span class=\"kw-chiffre\"> 48h</span></strong> pour évaluer la cinétique (cf. ci-dessous).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Cinétique des β-hCG à<span class=\"kw-chiffre\"> 48h</span> — Interprétation</h4>\n\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-clinique\">Évolution</span> à<span class=\"kw-chiffre\"> 48h</span></th><th>Diagnostic probable</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Taux qui double</strong> (<span class=\"kw-chiffre\">× 2 en 48h</span>)</td>\n            <td>Plutôt en faveur d’une <span class=\"kw-etio\">grossesse évolutive</span> — <span class=\"kw-etio\">GIU</span> le plus souvent, parfois <span class=\"kw-alerte\">GEU</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Taux qui décroît d’un <span class=\"kw-chiffre\">facteur 2</span></strong></td>\n            <td>Plutôt en faveur d’une <span class=\"kw-etio\">fausse couche spontanée (FCS)</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Taux qui <span class=\"kw-alerte\">stagne</span> ou augmentation insuffisante</strong></td>\n            <td>Plutôt en faveur d’une <span class=\"kw-alerte\">GEU</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Seuil de discrimination GIU <span class=\"kw-bio\">vs</span> GEU.</strong> Si hCG <span class=\"kw-chiffre\">&lt; 2 000 UI/L</span> : <strong>seuil d’augmentation des hCG au contrôle à<span class=\"kw-chiffre\"> 48h</span> <span class=\"kw-chiffre\">&lt; 15 %</span></strong> pour écarter une GIU évolutive. <br>\n        <strong>Piège KB :</strong> <span class=\"kw-alerte\">toute cinétique peut quand même se voir en cas de GEU</span> — la cinétique oriente mais n’élimine jamais formellement une GEU.\n      </div>\n\n      <h4>Résumé décisionnel</h4>\n\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>Conduite à tenir</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>β-hCG <span class=\"kw-chiffre\">&gt; 1 500</span> + <span class=\"kw-imagerie\">vacuité utérine</span></strong></td>\n            <td><span class=\"kw-alerte\">GEU jusqu’à preuve du contraire</span> → recherche signe direct écho + bilan préop.</td>\n          </tr>\n          <tr>\n            <td><strong>β-hCG <span class=\"kw-chiffre\">&lt; 1 500</span> + asymptomatique</strong></td>\n            <td><span class=\"kw-def\">Surveillance</span> — répéter <span class=\"kw-bio\">β-hCG</span> + écho à <span class=\"kw-chiffre\">48h</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>β-hCG décroissants <span class=\"kw-chiffre\">× 2</span></strong></td>\n            <td><span class=\"kw-etio\">FCS</span> probable — <span class=\"kw-def\">surveillance</span> jusqu’à négativation.</td>\n          </tr>\n          <tr>\n            <td><strong>β-hCG stagnants ou augmentation <span class=\"kw-chiffre\">&lt; 15 %</span></strong></td>\n            <td><span class=\"kw-alerte\">GEU</span> probable — discuter <span class=\"kw-ttt\">MTX</span> <span class=\"kw-bio\">vs</span> cœlioscopie selon contexte.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Signes de gravité</span> quel que soit le taux</strong></td>\n            <td><span class=\"kw-alerte\">Cœlioscopie en urgence</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 24 — Complications de la grossesse · 42 — Aménorrhée · 43 — Hémorragie génitale chez la femme</em></p>","frequence":5},{"id":"25-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître le bilan biologique pré opératoire en cas de diagnostic de GEU","contenu":"<p>Le bilan <span class=\"kw-ttt\">biologique</span> préopératoire suit les standards d’une <span class=\"kw-ttt\">chirurgie</span> urgente avec <span class=\"kw-alerte\">risque hémorragique</span>, complété par un bilan spécifique selon la stratégie thérapeutique (MTX ou chirurgie).</p>\n\n      <h4><span class=\"kw-def\">Bilan préopératoire</span> standard</h4>\n\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Indication</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\">NFS-plaquettes</span></td>\n            <td>Recherche d’une <span class=\"kw-clinique\">anémie</span> (saignement) ; numération plaquettaire avant geste.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">TP / TCA</span></td>\n            <td>Bilan d’hémostase préopératoire.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Groupe sanguin / Rhésus + RAI</span></td>\n            <td>Indispensable avant tout geste à risque <span class=\"kw-etio\">hémorragique</span>. Permet la <strong>prévention de l’allo-immunisation anti-D</strong> si Rh-.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Consultation anesthésique</span></td>\n            <td>Évaluation préopératoire systématique.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Bilan pré-<span class=\"kw-ttt\">méthotrexate</span> (si traitement médical envisagé)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Justification</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\">NFS</span></td>\n            <td>Recherche cytopénies préexistantes (CI MTX : leucopénie &lt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span>G</span>, thrombopénie &lt; 50G, anémie &lt;<span class=\"kw-chiffre\"> 9 g/dL</span>).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">TP / TCA</span></td>\n            <td>Hémostase.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Bilan rénal</span> (<span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">clairance</span>)</td>\n            <td>CI MTX si <strong><span class=\"kw-bio\">clairance</span> <span class=\"kw-chiffre\">&lt; 20-30 mL/min</span></strong>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Bilan hépatique</span> (<span class=\"kw-bio\">ASAT</span>, <span class=\"kw-bio\">ALAT</span>, <span class=\"kw-bio\">GGT</span>, <span class=\"kw-bio\">PAL</span>)</td>\n            <td>CI MTX si troubles sévères de la fonction hépatique.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Radiographie thoracique (RXT)</span></td>\n            <td>Recherche d’une pneumopathie sous-jacente (CI MTX : <span class=\"kw-def\">tuberculose</span>, <span class=\"kw-etio\">VIH</span>, infections graves).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Bilan complémentaire selon contexte</h4>\n\n      <ul>\n        <li><span class=\"kw-bio\">HemoCue®</span> — <strong>si signes cliniques ou échographiques de gravité</strong> (mesure rapide de l’<span class=\"kw-bio\">hémoglobine</span> au lit du malade)</li>\n        <li><span class=\"kw-bio\">Groupe sanguin du conjoint</span> — <strong>si patiente Rh-</strong>, pour décider la <strong>prévention de l’allo-immunisation anti-Rh1 par Ig anti-D</strong></li>\n        <li><span class=\"kw-bio\">Dosage de la progestéronémie</span> — peu pratiqué, mais si <strong>progestéronémie <span class=\"kw-chiffre\">&gt; 25 ng/mL</span></strong> = <span class=\"kw-ci\">grossesse</span> encore évolutive</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments · 332 — État de <span class=\"kw-alerte\">choc</span> · 27 — Prévention des risques fœtaux</em></p>","frequence":0},{"id":"25-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître le principe du traitement chirurgical en cas de diagnostic positif de GEU","contenu":"<p>Le traitement chirurgical est indiqué dans toutes les <span class=\"kw-alerte\">GEU symptomatiques</span> et dans les formes pour lesquelles le <span class=\"kw-ttt\">méthotrexate</span> est <span class=\"kw-ci\">contre-indiqué</span>. La <strong>cœlioscopie est le gold standard</strong> ; la laparotomie reste réservée aux situations d’<span class=\"kw-alerte\">urgence</span> vitale.</p>\n\n      <h4>Voie d’abord</h4>\n\n      <table >\n        <thead>\n          <tr><th>Voie</th><th>Indication</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Cœlioscopie</strong></td>\n            <td>\n              <span class=\"kw-alerte\">Gold standard</span> du traitement chirurgical de la GEU :<br>\n              <strong>Confirme</strong> le diagnostic<br>\n              <strong>Précise</strong> la localisation de la GEU<br>\n              <strong>Permet</strong> le traitement dans le même temps opératoire<br>\n              <strong>Retrouve</strong> les FR (adhérences, séquelles d’IGH)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Laparotomie</strong></td>\n            <td>\n              <em>Seules indications actuelles :</em><br>\n              <span class=\"kw-alerte\">Hémopéritoine massif et choc hypovolémique</span><br>\n              <strong><span class=\"kw-ci\">Contre-indications</span> générales ou locales</strong> à la cœlioscopie\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Indications chirurgicales</h4>\n\n      <div class=\"callout callout-danger\">\n        <strong>Indications chirurgicales = URGENCES.</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Patiente algique</span> ⭐</li>\n          <li><strong>β-hCG <span class=\"kw-chiffre\">&gt; 5 000 UI/L</span></strong></li>\n          <li><strong><span class=\"kw-clinique\">Masse</span> latéro-utérine <span class=\"kw-chiffre\">&gt; 4 cm</span></strong> à l’<span class=\"kw-imagerie\">échographie</span></li>\n          <li><span class=\"kw-alerte\">GEU tubaire avec embryon et activité cardiaque</span> à l’<span class=\"kw-imagerie\">échographie</span></li>\n          <li><span class=\"kw-alerte\">Instabilité hémodynamique, défense abdominale, hémopéritoine</span> = URGENCES CHIRURGICALES</li>\n          <li>Autres CI du traitement médical (impossibilité de <span class=\"kw-def\">suivi</span> ambulatoire...)</li>\n        </ul>\n      </div>\n\n      <h4>Conditionnement préopératoire</h4>\n\n      <ul>\n        <li><strong>Expansion volémique</strong> (cristalloïdes)</li>\n        <li><strong>2 voies veineuses périphériques</strong> de bon calibre</li>\n        <li><strong><span class=\"kw-def\">Bilan préopératoire</span></strong> (cf. obj-7) en <span class=\"kw-alerte\">urgence</span></li>\n        <li><span class=\"kw-bio\">HemoCue®</span> au lit du malade</li>\n        <li><strong>Appel du médecin anesthésiste-réanimateur</strong></li>\n      </ul>\n\n      <h4>Geste chirurgical — Traitement conservateur</h4>\n\n      <table >\n        <thead>\n          <tr><th>Volet</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Technique</strong></td>\n            <td><span class=\"kw-ttt\">Salpingotomie</span> (incision de la trompe) puis extraction de la <span class=\"kw-ci\">grossesse</span> par <strong>aspiration</strong> (examen anatomopathologique du contenu).</td>\n          </tr>\n          <tr>\n            <td><strong>Indications</strong></td>\n            <td><strong>Privilégié pour préserver la fertilité</strong>, surtout si <span class=\"kw-chiffre\">&gt; 35 ans</span> ou ATCD d’infertilité.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Surveillance</span></strong></td>\n            <td>Dosage des β-hCG en postopératoire : <span class=\"kw-chiffre\">1 ×/semaine jusqu’à négativation</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Risque d’échec</strong></td>\n            <td><span class=\"kw-chiffre\">5-15 %</span> (rétention de tissu trophoblastique persistant).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Geste chirurgical — Traitement radical</h4>\n\n      <table >\n        <thead>\n          <tr><th>Volet</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Technique</strong></td>\n            <td><span class=\"kw-ttt\">Salpingectomie</span> (ablation de la trompe).</td>\n          </tr>\n          <tr>\n            <td><strong>Indications</strong></td>\n            <td>\n              <strong>Saignement trop important</strong><br>\n              <strong>État tubaire trop altéré</strong> pour conservation<br>\n              <em>Surtout chez une patiente âgée n’ayant plus de désir de <span class=\"kw-ci\">grossesse</span></em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Surveillance</span> β-hCG</strong></td>\n            <td><span class=\"kw-alerte\">Pas de surveillance des β-hCG en post-opératoire</span> ❌ (toute la trompe contenant le trophoblaste est retirée).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Pronostic</span> fertilité</strong></td>\n            <td>\n              <strong>Chances de <span class=\"kw-ci\">grossesse</span> probablement identiques</strong> en cas de salpingectomie si trompe controlatérale normale (à rassurer la patiente).<br>\n              <em>Essai randomisé n’a pas montré de différence de fertilité entre salpingectomie et salpingotomie.</em>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 40 — Algies pelviennes · 332 — État de <span class=\"kw-alerte\">choc</span> · 50 — Pathologie génito-scrotale</em></p>","frequence":0},{"id":"25-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître les informations à délivrer à la patiente avant la prise en charge chirurgicale","contenu":"<p>L’information de la patiente avant la prise en charge chirurgicale d’une GEU est une <span class=\"kw-def\">obligation médico-légale</span> (<span class=\"kw-def\">consentement éclairé</span>). Elle aborde le diagnostic, les choix thérapeutiques, les conséquences sur la fertilité et la <span class=\"kw-def\">prévention secondaire</span>.</p>\n\n      <h4>Informations à transmettre</h4>\n\n      <table >\n        <thead>\n          <tr><th>Volet</th><th>Contenu de l’information</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Diagnostic</strong></td>\n            <td>\n              <span class=\"kw-def\">Annonce</span> de la GEU<br>\n              Explication du <strong>caractère urgent et potentiellement vital</strong> en cas de <span class=\"kw-alerte\">rupture</span><br>\n              Rappel que le diagnostic peut nécessiter une <span class=\"kw-clinique\">cœlioscopie diagnostique</span> en cas de doute persistant\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Choix thérapeutique</strong></td>\n            <td>\n              <strong>Option chirurgicale conservatrice</strong> (<span class=\"kw-ttt\">salpingotomie</span>) : préserve la trompe mais risque d’échec <span class=\"kw-chiffre\">5-15 %</span> + <span class=\"kw-def\">surveillance</span> β-hCG hebdomadaire jusqu’à négativation<br>\n// [13/06/2026] Cap « option C » LEVÉ : stars = comptage ⭐ brut de la source (plus de plafond à 5). hot = (stars <span class=\"kw-chiffre\">≥ 6</span>).\n              <strong>Option chirurgicale radicale</strong> (<span class=\"kw-ttt\">salpingectomie</span>) : pas de surveillance β-hCG, chances de <span class=\"kw-ci\">grossesse</span> identiques si trompe controlatérale normale<br>\n              <strong>Option médicale (<span class=\"kw-ttt\">MTX</span>)</strong> si critères réunis (cf. obj-10) : éviter une <span class=\"kw-ttt\">chirurgie</span>, mais contraception <span class=\"kw-chiffre\">3 mois</span> post-MTX\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Conséquences sur la fertilité</strong></td>\n            <td>\n              <strong>Taux de <span class=\"kw-def\">récidive de GEU</span> :</strong> <span class=\"kw-chiffre\">≈ 20 %</span> quel que soit le traitement<br>\n              <strong>Fertilité préservée</strong> dans la majorité des cas (essai randomisé : pas de différence salpingectomie <span class=\"kw-bio\">vs</span> salpingotomie)<br>\n              <strong>Recommandation</strong> d’une <span class=\"kw-imagerie\">échographie</span> précoce pour la <span class=\"kw-ci\">grossesse</span> suivante ⭐\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Prévention de l’allo-immunisation</strong></td>\n            <td>Si <span class=\"kw-clinique\">Rh-</span> : <span class=\"kw-ttt\">Ig anti-D</span> systématique en post-opératoire (cf. obj-11).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Dépistage IST</span></strong></td>\n            <td>Si la cœlioscopie retrouve des <strong>séquelles d’IGH</strong> : <span class=\"kw-def\">dépistage</span> IST chez la <strong>patiente et son partenaire</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Contraception</strong></td>\n            <td>\n              <span class=\"kw-ttt\">Contraception 3 mois</span> après MTX (<span class=\"kw-alerte\">effet tératogène</span>)<br>\n              Discuter le choix d’une contraception adaptée selon profil et désir de <span class=\"kw-ci\">grossesse</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Formalités</h4>\n\n      <ul>\n        <li><strong>Consultation préopératoire</strong> avec gynécologue et anesthésiste</li>\n        <li><strong>Information écrite</strong> remise (fiche INPES / société savante)</li>\n        <li><strong>Consentement éclairé</strong> signé</li>\n        <li><strong>Soutien psychologique</strong> proposé (<span class=\"kw-def\">annonce</span> d’un échec de <span class=\"kw-ci\">grossesse</span> + possible impact sur fertilité)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 1 — Relation médecin-malade · 7 — Dossier médical, information, secret médical · 27 — Prévention des risques fœtaux · 36 — Contraception</em></p>","frequence":0},{"id":"25-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître la notion de traitement médical possible en cas de GEU asymptomatique","contenu":"<p>Le <span class=\"kw-ttt\">méthotrexate (MTX)</span> par voie IM est une alternative à la <span class=\"kw-ttt\">chirurgie</span> dans les <strong>GEU paucisymptomatiques et de faible volume</strong>. Il évite une intervention chirurgicale mais impose une <strong><span class=\"kw-def\">surveillance</span> hebdomadaire rigoureuse</strong>.</p>\n\n      <h4>Indications du <span class=\"kw-ttt\">méthotrexate</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Seuil</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Symptomatologie</strong></td>\n            <td><span class=\"kw-clinique\">Paucisymptomatique</span> (peu douloureuse, hémodynamique stable)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span></strong></td>\n            <td><strong>GEU visible</strong> à l’<span class=\"kw-imagerie\">échographie</span></td>\n          </tr>\n          <tr>\n            <td><strong>β-hCG</strong></td>\n            <td><span class=\"kw-chiffre\">&lt; 5 000 UI/L</span> (traitement possible jusqu’à <span class=\"kw-chiffre\">10 000 UI/L</span> en pratique)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-ci\">Contre-indications</span> liées à la GEU</h4>\n\n      <ul>\n        <li>Patiente symptomatique</li>\n        <li>β-hCG &gt; 10 <span class=\"kw-chiffre\">000 UI/L</span></li>\n        <li><span class=\"kw-clinique\">Masse</span> latéro-utérine &gt;<span class=\"kw-chiffre\"> 4 cm</span> à l’<span class=\"kw-imagerie\">échographie</span></li>\n        <li>GEU tubaire avec embryon et activité cardiaque à l’<span class=\"kw-imagerie\">échographie</span></li>\n        <li>Suspicion de <span class=\"kw-alerte\">rupture</span> tubaire</li>\n        <li>Instabilité hémodynamique</li>\n        <li>Hémopéritoine dépassant le fond utérin</li>\n      </ul>\n\n      <h4><span class=\"kw-ci\">Contre-indications</span> liées au <span class=\"kw-ttt\">méthotrexate</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Contre-indications</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>\n              <span class=\"kw-ci\">Allaitement</span><br>\n              <span class=\"kw-ci\">Alcoolisme</span><br>\n              Troubles sévères de la fonction hépatique<br>\n              Troubles de la fonction rénale (<span class=\"kw-bio\">clairance</span> &lt;<span class=\"kw-chiffre\"> 20-30 mL</span>/min)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hématologiques</strong></td>\n            <td>\n              <span class=\"kw-ci\">Hypoplasie médullaire</span><br>\n              <span class=\"kw-ci\">Leucopénie &lt; 2 G/L</span><br>\n              <span class=\"kw-ci\">Thrombopénie &lt; 50 G/L</span><br>\n              <span class=\"kw-ci\">Anémie &lt; 9 g/dL</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Infectieuses</strong></td>\n            <td><span class=\"kw-ci\">Tuberculose</span>, <span class=\"kw-ci\">VIH</span> ou autre syndrome d’immunodéficience</td>\n          </tr>\n          <tr>\n            <td><strong>Digestives</strong></td>\n            <td>Ulcères de la cavité buccale, maladie ulcéreuse gastro-intestinale évolutive</td>\n          </tr>\n          <tr>\n            <td><strong>Vaccinales</strong></td>\n            <td>Administration concomitante de <span class=\"kw-ci\">vaccins vivants</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Autres <span class=\"kw-ci\">contre-indications</span></h4>\n\n      <ul>\n        <li>Troubles de la coagulation contre-indiquant l’injection IM</li>\n        <li><span class=\"kw-ci\">Refus de la patiente</span> (choix formel pour un traitement chirurgical)</li>\n        <li>Difficultés de compréhension ou de <strong><span class=\"kw-def\">surveillance</span> en ambulatoire</strong> : mauvaise observance, éloignement géographique, isolement</li>\n      </ul>\n\n      <h4>Modalités de l’injection</h4>\n\n      <table >\n        <thead>\n          <tr><th>Paramètre</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Voie</strong></td>\n            <td><span class=\"kw-ttt\">Voie IM</span> en <span class=\"kw-chiffre\">première intention</span>. <strong>Injection in situ possible</strong> pour les localisations interstitielles, cervicales ou sur cicatrice de césarienne.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Bilan préthérapeutique</span></strong></td>\n            <td><span class=\"kw-bio\">NFS</span>, bilan d’hémostase, <span class=\"kw-bio\">bilan rénal</span>, <span class=\"kw-bio\">bilan hépatique</span> (cf. obj-7).</td>\n          </tr>\n          <tr>\n            <td><strong>Précautions</strong></td>\n            <td>\n              <span class=\"kw-ttt\">Contraception 3 mois</span> après injection (effet <span class=\"kw-ci\">tératogène</span>)<br>\n              <strong>Supplémentation par <span class=\"kw-bio\">folates</span> non nécessaire</strong> ❌ (1-2 injections seulement)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Surveillance</span> post-injection</h4>\n\n      <table >\n        <thead>\n          <tr><th>Paramètre</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Fréquence</strong></td>\n            <td><span class=\"kw-chiffre\">1 ×/semaine</span></td>\n          </tr>\n          <tr>\n            <td><strong>Modalités</strong></td>\n            <td>Évaluation clinique + dosage <span class=\"kw-bio\">β-hCG</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span> attendue</strong></td>\n            <td>\n              Augmentation initiale transitoire des hCG possible ⭐ (à ne pas confondre avec un échec)<br>\n              <strong>Résultat normal à <span class=\"kw-chiffre\">J7</span> :</strong> β-hCG <span class=\"kw-chiffre\">&lt; taux à J0</span> ou <span class=\"kw-chiffre\">&lt; 85 % du taux à J4</span> (si disponible)<br>\n              <strong><span class=\"kw-def\">Critères de</span> guérison :</strong> β-hCG <span class=\"kw-alerte\">non détectables</span> (généralement obtenu en <span class=\"kw-chiffre\">≈ 1 mois</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Échec du traitement</strong></td>\n            <td>\n              <strong>Fréquence :</strong> <span class=\"kw-chiffre\">25 %</span><br>\n              <strong>FR d’échec :</strong> ATCD de GEU traitée médicalement ou chirurgicalement<br>\n              <strong>CAT :</strong> <span class=\"kw-ttt\">2ᵉ injection de méthotrexate</span> ou <span class=\"kw-ttt\">cœlioscopie</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Risque post-injection à connaître ⭐.</strong> <span class=\"kw-alerte\">Rupture tubaire</span> possible <strong>après injection de MTX</strong> :\n        <ul>\n          <li><strong>Signe d’appel :</strong> <span class=\"kw-alerte\">douleur abdominale importante</span> ou <span class=\"kw-alerte\">malaise</span> (à différencier de la sensibilité du côté de la GEU à <span class=\"kw-chiffre\">J3</span> qui est habituelle/normale)</li>\n          <li><strong>CAT :</strong> <span class=\"kw-ttt\">chirurgie en urgence</span></li>\n        </ul>\n      </div>\n\n      <h4>Effets secondaires du <span class=\"kw-ttt\">méthotrexate</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Système</th><th>Manifestations</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Hématologiques</strong></td>\n            <td><span class=\"kw-alerte\">Cytopénies</span> (leucopénie, anémie, thrombopénie), macrocytose</td>\n          </tr>\n          <tr>\n            <td><strong>Digestifs</strong></td>\n            <td>Mucite, <span class=\"kw-clinique\">nausées</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hépatiques</strong></td>\n            <td>Augmentation des transaminases (peut induire une fibrose hépatique au long cours)</td>\n          </tr>\n          <tr>\n            <td><strong>Rénaux</strong></td>\n            <td><span class=\"kw-ci\">Insuffisance rénale</span> (toxicité tubulaire directe ou indirecte par précipitation intra-tubulaire)</td>\n          </tr>\n          <tr>\n            <td><strong>Cutanés</strong></td>\n            <td><span class=\"kw-clinique\">Prurit</span>, érythème, photosensibilisation, ulcérations cutanéo-muqueuses (surdosage ou interaction médicamenteuse)</td>\n          </tr>\n          <tr>\n            <td><strong>Respiratoires</strong></td>\n            <td>Pneumopathie interstitielle (pneumopathie aiguë d’<span class=\"kw-ci\">hypersensibilité</span>), fibrose pulmonaire</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Cas particulier — Abstention thérapeutique</h4>\n\n      <div class=\"callout callout-info\">\n        <strong>Abstention thérapeutique surveillée</strong> — discutée si <strong>tous les critères</strong> sont réunis :\n        <ul>\n          <li><span class=\"kw-clinique\">Patiente asymptomatique</span></li>\n          <li><strong>β-hCG initial <span class=\"kw-chiffre\">&lt; 1 000 UI/L</span></strong></li>\n          <li><strong>Cinétique des β-hCG : décroissance progressive et constante</strong></li>\n          <li><strong>Bonne observance</strong> de la patiente pour la <span class=\"kw-def\">surveillance</span></li>\n        </ul>\n        <strong>Surveillance :</strong> dosage β-hCG toutes les <span class=\"kw-chiffre\">48h</span> + contrôle clinique et échographique <span class=\"kw-chiffre\">1 ×/semaine</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments · 201 — Transplantation d’organe · 192 — Pathologie <span class=\"kw-etio\">auto-immune</span> · 36 — Contraception</em></p>","frequence":1},{"id":"25-12","rang":"A","rubrique":"Prise en charge","titre":"Connaître les mesures associées à la prise en charge : prévention de l’alloimmunisation anti-D, prévention secondaire","contenu":"<p>La prise en charge complète d’une GEU ne s’arrête pas au traitement initial : elle inclut la <strong>prévention de l’allo-immunisation anti-D</strong> chez les patientes Rh- et une <strong><span class=\"kw-def\">prévention secondaire</span></strong> visant à limiter le risque de récidive et à dépister précocement une nouvelle GEU.</p>\n\n      <h4>Prévention de l’allo-immunisation anti-D</h4>\n\n      <table >\n        <thead>\n          <tr><th>Volet</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Indication</strong></td>\n            <td><strong>Toute patiente Rh-</strong> présentant une GEU (quel que soit le traitement : MTX ou <span class=\"kw-ttt\">chirurgie</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Vérification préalable</strong></td>\n            <td><span class=\"kw-bio\">Groupe sanguin du conjoint</span> — si conjoint Rh+ ou inconnu : Ig anti-D systématiques.</td>\n          </tr>\n          <tr>\n            <td><strong>Traitement</strong></td>\n            <td><span class=\"kw-ttt\">Immunoglobulines anti-D (Ig anti-D)</span> en IM, à administrer dans les <span class=\"kw-chiffre\">72 heures</span> suivant l’événement.</td>\n          </tr>\n          <tr>\n            <td><strong>Objectif</strong></td>\n            <td>Prévenir la survenue d’<strong><span class=\"kw-bio\">anticorps anti-Rh1</span> (anti-D)</strong> chez la mère, qui exposeraient les grossesses ultérieures à une <span class=\"kw-alerte\">maladie hémolytique du nouveau-né</span> en cas de fœtus Rh+.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Prévention secondaire</span> — Dépistage des IST</h4>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-def\">Dépistage</span> IST.</strong> Si la cœlioscopie retrouve des <strong>séquelles d’IGH</strong> (adhérences, <span class=\"kw-clinique\">hydrosalpinx</span>, lésions tubaires inflammatoires), réaliser systématiquement un <strong>dépistage des IST chez la patiente et son partenaire</strong> :\n        <ul>\n          <li><span class=\"kw-bio\">PCR Chlamydia trachomatis</span> (<span class=\"kw-bio\">PCR</span> sur 1ᵉʳ jet urinaire ou prélèvement vaginal)</li>\n          <li><span class=\"kw-bio\">PCR gonocoque</span></li>\n          <li><span class=\"kw-bio\">Sérologies syphilis, VIH, VHB, VHC</span></li>\n        </ul>\n        Le traitement des IST identifiées chez la patiente <em>et</em> le partenaire prévient la récurrence des IGH et donc le risque de nouvelle GEU.\n      </div>\n\n      <h4><span class=\"kw-def\">Prévention secondaire</span> — <span class=\"kw-def\">Suivi</span> de la fertilité et <span class=\"kw-ci\">grossesse</span> ultérieure</h4>\n\n      <table >\n        <thead>\n          <tr><th>Mesure</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Taux de récidive de GEU</strong></td>\n            <td><span class=\"kw-chiffre\">≈ 20 %</span> quel que soit le traitement (<span class=\"kw-ttt\">MTX</span>, <span class=\"kw-ttt\">salpingotomie</span>, <span class=\"kw-ttt\">salpingectomie</span>).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span> précoce pour la <span class=\"kw-ci\">grossesse</span> suivante</strong> ⭐</td>\n            <td>\n              <strong>Recommandation systématique</strong> — toute <span class=\"kw-ci\">grossesse</span> suivante doit bénéficier d’une <span class=\"kw-imagerie\">échographie endovaginale précoce</span> (vers 6 SA) pour confirmer la localisation intra-utérine.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Contraception</strong></td>\n            <td>\n              <span class=\"kw-ttt\">Contraception 3 mois</span> obligatoire après MTX (<span class=\"kw-alerte\">effet tératogène</span>)<br>\n              Discussion du choix contraceptif selon profil et désir de <span class=\"kw-ci\">grossesse</span> (cf. obj-2 sur les FR contraceptifs)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Conseil tabagique</strong></td>\n            <td>Le <span class=\"kw-clinique\">tabagisme</span> est un FR de GEU dose-dépendant — <strong><span class=\"kw-ttt\">sevrage</span> tabagique</strong> à proposer systématiquement.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Pronostic</span> fertilité</strong></td>\n            <td>\n              <strong>Chances de <span class=\"kw-ci\">grossesse</span></strong> probablement identiques entre salpingotomie et salpingectomie si trompe controlatérale normale (à rassurer la patiente).<br>\n              <em>Essai randomisé : pas de différence de fertilité entre les 2 techniques.</em>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Soutien psychologique</h4>\n\n      <ul>\n        <li><span class=\"kw-def\">Annonce</span> d’un <strong>échec de <span class=\"kw-ci\">grossesse</span></strong> (<span class=\"kw-def\">deuil périnatal</span>)</li>\n        <li>Crainte d’une <strong>récidive</strong> ou d’une <strong>infertilité</strong></li>\n        <li>Proposer un <strong>accompagnement psychologique</strong> ou un <span class=\"kw-def\">suivi</span> en consultation gynécologique dédiée</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 27 — Prévention des risques fœtaux · 162 — IST · 36 — Contraception · 75 — Addiction <span class=\"kw-etio\">tabac</span></em></p>","frequence":1}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/ectopic-pregnancy","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/cases/ectopic-pregnancy-distribution-diagram","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"GEU diagnostiquée ou fortement suspectée — Premier tri = signes de gravité et état hémodynamique","detail":"<h4>CAT thérapeutique devant une GEU — Tri sur la gravité, puis β-hCG · symptômes · activité cardiaque</h4>","branches":[{"to":"t-urgence","label":"Signes de gravité présents","color":"red"},{"to":"q-stable","label":"Hémodynamique stable, pas de gravité","color":"blue"}]},{"id":"t-urgence","kind":"terminal","label":"Urgence chirurgicale — cœlioscopie sans délai","color":"red","detail":"<h4><span class=\"kw-alerte\"><span class=\"kw-def\">Critères de</span> gravité</span></h4><ul><li><span class=\"kw-alerte\">Instabilité hémodynamique</span> : <span class=\"kw-clinique\">hypotension</span>, tachycardie</li><li><span class=\"kw-clinique\">Défense ou contracture</span> abdominale</li><li><span class=\"kw-alerte\">Hémopéritoine</span> : épanchement dépassant le fond utérin, sang dans l’espace de Morisson</li><li>Suspicion de <span class=\"kw-alerte\">rupture tubaire</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Cœlioscopie</span> en <span class=\"kw-alerte\">urgence</span> = gold standard (confirme le diagnostic <em>et</em> traite)</li><li><span class=\"kw-ttt\">Laparotomie</span> si hémopéritoine massif ou <span class=\"kw-alerte\">choc hypovolémique</span></li><li>Conditionnement : <span class=\"kw-ttt\">2 VVP</span>, expansion volémique, <span class=\"kw-bio\">HemoCue®</span>, <span class=\"kw-def\">bilan préopératoire</span>, appel de l’anesthésiste</li></ul><h4>Geste opératoire</h4><ul><li><span class=\"kw-ttt\">Salpingectomie</span> (radical) si saignement important ou trompe trop altérée</li><li><span class=\"kw-ttt\">Salpingotomie</span> (conservateur) pour préserver la fertilité si possible</li></ul>"},{"id":"q-stable","kind":"decision","label":"Patiente symptomatique (algique) ou critères de chirurgie ? — β-hCG · taille de la masse · activité cardiaque · CI au méthotrexate","branches":[{"to":"t-chir","label":"Symptomatique / critères chirurgicaux","color":"amber"},{"to":"q-medical","label":"Pauci- / asymptomatique","color":"blue"}]},{"id":"t-chir","kind":"terminal","label":"Traitement chirurgical — cœlioscopie programmée","color":"amber","detail":"<h4>Indications</h4><ul><li>Patiente <span class=\"kw-clinique\">algique</span> ⭐</li><li>β-hCG <span class=\"kw-chiffre\">&gt; 5 000 UI/L</span></li><li><span class=\"kw-clinique\">Masse</span> latéro-utérine <span class=\"kw-chiffre\">&gt; 4 cm</span> à l’<span class=\"kw-imagerie\">échographie</span></li><li>GEU tubaire avec <span class=\"kw-clinique\">embryon + activité cardiaque</span></li><li><span class=\"kw-ci\">Contre-indication</span> au traitement médical (<span class=\"kw-def\">suivi</span> ambulatoire impossible…)</li></ul><h4>Voie d’abord</h4><ul><li><span class=\"kw-ttt\">Cœlioscopie</span> = gold standard (confirme le diagnostic, localise la GEU, recherche les FR : adhérences, séquelles d’IGH)</li></ul><h4>Conservateur — salpingotomie</h4><ul><li>Privilégié pour <span class=\"kw-alerte\">préserver la fertilité</span> (surtout &gt;<span class=\"kw-chiffre\"> 35 ans</span> ou ATCD d’infertilité)</li><li><span class=\"kw-def\">Surveillance</span> <span class=\"kw-bio\">β-hCG 1×/semaine</span> jusqu’à négativation</li><li>Risque d’échec : <span class=\"kw-chiffre\">5–15 %</span></li></ul><h4>Radical — salpingectomie</h4><ul><li>Si <span class=\"kw-alerte\">saignement important</span> ou état tubaire trop altéré</li><li><span class=\"kw-chiffre\">Pas</span> de <span class=\"kw-def\">surveillance</span> des β-hCG en postopératoire</li><li>Fertilité conservée si trompe controlatérale normale (rassurer la patiente)</li></ul>"},{"id":"q-medical","kind":"decision","label":"β-hCG initiale et cinétique ? — Éligibilité au méthotrexate vs abstention surveillée","branches":[{"to":"t-mtx","label":"β-hCG < 5 000 (–10 000), GEU visible, pas de CI","color":"green"},{"to":"t-abstention","label":"β-hCG < 1 000 UI/L en décroissance","color":"blue"}]},{"id":"t-mtx","kind":"terminal","label":"Traitement médical — Méthotrexate (IM)","color":"green","detail":"<h4>Indications</h4><ul><li>Paucisymptomatique</li><li>GEU <span class=\"kw-clinique\">visible à l’échographie</span></li><li>β-hCG <span class=\"kw-chiffre\">&lt; 5 000 UI/L</span> (possible jusqu’à 10 000 en pratique)</li></ul><h4>Voie</h4><ul><li><span class=\"kw-ttt\">IM</span> ; injection <em>in situ</em> possible pour les localisations interstitielles, cervicales ou sur cicatrice de césarienne</li></ul><h4><span class=\"kw-ci\">Contre-indications</span> (liées à la GEU)</h4><ul><li>Patiente <span class=\"kw-clinique\">symptomatique</span></li><li>β-hCG <span class=\"kw-chiffre\">&gt; 10 000 UI/L</span>, <span class=\"kw-clinique\">masse</span> <span class=\"kw-chiffre\">&gt; 4 cm</span></li><li>Embryon avec <span class=\"kw-clinique\">activité cardiaque</span></li><li>Suspicion de <span class=\"kw-alerte\">rupture</span> / instabilité / hémopéritoine</li></ul><h4><span class=\"kw-ci\">Contre-indications</span> (liées au MTX)</h4><ul><li><span class=\"kw-ci\">Allaitement</span>, alcoolisme</li><li>Insuffisance <span class=\"kw-bio\">hépatique</span> ou <span class=\"kw-bio\">rénale</span> sévère (<span class=\"kw-bio\">clairance</span> &lt;<span class=\"kw-chiffre\"> 20–30 mL</span>/min)</li><li>Cytopénies, immunodépression (<span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">tuberculose</span>), ulcère digestif, vaccin vivant</li><li>Mauvaise observance ou <span class=\"kw-def\">surveillance</span> ambulatoire impossible</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">β-hCG + clinique 1×/semaine</span></li><li>Résultat normal à <span class=\"kw-chiffre\">J7</span> : β-hCG &lt; J0 (ou &lt;<span class=\"kw-chiffre\"> 85 %</span> de J4)</li><li>Guérison = β-hCG <span class=\"kw-chiffre\">indétectable</span> (~<span class=\"kw-chiffre\">1 mois</span>) · contraception <span class=\"kw-chiffre\">3 mois</span> (<span class=\"kw-ci\">tératogène</span>)</li></ul><h4>Échec (<span class=\"kw-chiffre\">25 %</span>) et risque</h4><ul><li>Décroissance insuffisante → <span class=\"kw-ttt\">2ᵉ injection</span> de MTX ou <span class=\"kw-ttt\">cœlioscopie</span></li><li>⚠️ <span class=\"kw-alerte\">Rupture tubaire</span> possible après injection → <span class=\"kw-ttt\">chirurgie</span> en <span class=\"kw-alerte\">urgence</span></li></ul>"},{"id":"t-abstention","kind":"terminal","label":"Abstention thérapeutique — surveillance","color":"blue","detail":"<h4>Critères (TOUS réunis)</h4><ul><li>Patiente <span class=\"kw-clinique\">asymptomatique</span></li><li>β-hCG initiale <span class=\"kw-chiffre\">&lt; 1 000 UI/L</span></li><li>Cinétique en <span class=\"kw-bio\">décroissance progressive et constante</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>β-hCG <span class=\"kw-chiffre\">toutes les 48 h</span></li><li>Contrôle clinique + échographique <span class=\"kw-chiffre\">1×/semaine</span></li></ul><h4>Condition</h4><ul><li><span class=\"kw-alerte\">Bonne observance</span> indispensable (<span class=\"kw-def\">suivi</span> rapproché)</li></ul>"}]},"cards":[]};